namespace DotCharter.Tests;

/// <summary>
/// The test executable's entry point, replacing the one xUnit generates
/// (<c>XunitAutoGeneratedEntryPoint=false</c> in the csproj) so that a plain
/// <c>dotnet test</c> runs the default gate instead of everything. The body is
/// the generated one plus <see cref="DefaultRunFilter.Apply"/>; see
/// <c>DotCharter.Tests/README.md</c> for the fast, full and headless commands.
/// </summary>
internal static class TestEntryPoint
{
    public static int Main(string[] args)
    {
        var run = args.Any(arg => arg is "--server" or "--internal-msbuild-node")
            ? Xunit.MicrosoftTestingPlatform.TestPlatformTestFramework.RunAsync(
                DefaultRunFilter.Apply(args), SelfRegisteredExtensions.AddSelfRegisteredExtensions)
            : Xunit.Runner.InProc.SystemConsole.ConsoleRunner.Run(args);
        return run.GetAwaiter().GetResult();
    }
}

/// <summary>
/// The default filter of a plain <c>dotnet test</c>: the DEFAULT GATE. The
/// headless-UI suite (<c>*UiPerfSmokeTests</c>) shares Avalonia.Headless's
/// process-global dispatcher, so in the same testhost as the gate almost every
/// headless case fails and takes an unrelated gate test with it (AGENTS.md §
/// Validation). And the release lane (<c>tools/ci/release-lane.json</c>, the
/// heaviest corpus / integration / determinism classes) is run by
/// <c>Invoke-Gate.ps1 -ReleaseLane</c>, the merge train, the release preflight
/// and CI, not by every edit. So when <c>dotnet test</c> starts this executable
/// WITHOUT any filter, the gate's own exclusions are added. Any explicit filter (every script, CI job and
/// the release preflight passes one) switches the default off untouched, and so
/// does an IDE's test explorer, which talks JSON-RPC rather than
/// <c>dotnettestcli</c> and filters over the protocol.
/// </summary>
internal static class DefaultRunFilter
{
    /// <summary>The class pattern a plain <c>dotnet test</c> leaves out: the headless-UI suite.</summary>
    public const string ExcludedClasses = "*UiPerfSmokeTests";

    public static string[] Apply(string[] args) =>
        IsDotnetTestCli(args) && !args.Any(IsFilterOption)
            ? [.. args, "--filter-not-class", ExcludedClasses, .. ReleaseLane.ExclusionArgs()]
            : args;

    // `dotnet test` (MTP mode, opted into by the root global.json) starts the
    // executable with `--server dotnettestcli`; an IDE uses `--server` alone or
    // `--server jsonrpc`.
    private static bool IsDotnetTestCli(string[] args)
    {
        var server = Array.IndexOf(args, "--server");
        return server >= 0 && server + 1 < args.Length
            && string.Equals(args[server + 1], "dotnettestcli", StringComparison.OrdinalIgnoreCase);
    }

    // xUnit's --filter-class/-method/-namespace/-trait/-query (and their -not-
    // forms), MTP's --treenode-filter and --filter-uid, and the `name=value` form.
    private static bool IsFilterOption(string arg) =>
        arg.StartsWith("--filter", StringComparison.OrdinalIgnoreCase)
        || arg.StartsWith("--treenode-filter", StringComparison.OrdinalIgnoreCase);
}
